{
  "apiVersion": "v1",
  "kind": "Pod",
  "metadata": {
    "name": "app",
    "namespace": "default",
    "labels": {
      "app": "app"
    }
  },
  "spec": {
    "restartPolicy": "Always",
    "serviceAccountName": "default",
    "nodeName": "benchmark-sidecar-shared-volume-3aa97095-control-plane",
    "dnsPolicy": "ClusterFirst",
    "terminationGracePeriodSeconds": 30,
    "tolerations": [
      {
        "effect": "NoExecute",
        "key": "node.kubernetes.io/not-ready",
        "operator": "Exists",
        "tolerationSeconds": 300
      },
      {
        "effect": "NoExecute",
        "key": "node.kubernetes.io/unreachable",
        "operator": "Exists",
        "tolerationSeconds": 300
      }
    ],
    "containers": [
      {
        "command": [
          "sh",
          "-c",
          "httpd -f -p 8080 -h /srv"
        ],
        "image": "busybox:1.37.0",
        "imagePullPolicy": "IfNotPresent",
        "name": "web",
        "ports": [
          {
            "containerPort": 8080,
            "name": "http",
            "protocol": "TCP"
          }
        ],
        "resources": {},
        "terminationMessagePath": "/dev/termination-log",
        "terminationMessagePolicy": "File",
        "volumeMounts": [
          {
            "mountPath": "/srv",
            "name": "shared"
          },
          {
            "mountPath": "/var/run/secrets/kubernetes.io/serviceaccount",
            "name": "kube-api-access-mws47",
            "readOnly": true
          }
        ]
      },
      {
        "name": "page-writer",
        "image": "busybox:1.37.0",
        "imagePullPolicy": "IfNotPresent",
        "command": [
          "sh",
          "-c"
        ],
        "args": [
          "cat > /srv/index.html <<'EOF'\n<!DOCTYPE html>\n<html><head><title>Hello from app</title></head>\n<body><h1>Hello from the app Pod</h1>\n<p>Served from /srv by the web container, written by the page-writer container.</p>\n</body></html>\nEOF\nexec sleep 2073600\n"
        ],
        "volumeMounts": [
          {
            "name": "shared",
            "mountPath": "/srv"
          }
        ]
      }
    ],
    "volumes": [
      {
        "emptyDir": {},
        "name": "shared"
      }
    ]
  }
}
